"""Tensor-parallel linear layers (Megatron-style) built on torch.distributed.

Weight layout follows torch.nn.Linear: master_weight has shape
(out_features, in_features) and the forward computes y = x @ W^T + b.

- ColumnParallelLinear: W is split along the output dimension (the columns of
  W^T), each rank computes a slice of the output, and the slices are gathered
  (all_gather) and concatenated along the last dimension.
- RowParallelLinear: W is split along the input dimension (the rows of W^T),
  each rank computes a partial output from its slice of the input, and the
  partial outputs are summed (all_reduce). The bias is kept full on each rank
  and added after the reduction.
"""

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(numerator, denominator):
    assert numerator % denominator == 0, (
        f"{numerator} is not divisible by {denominator}"
    )
    return numerator // denominator


# ---------------------------------------------------------------------------
# Communication primitives with correct autograd semantics
# ---------------------------------------------------------------------------

def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _all_gather_last_dim(x):
    world_size = _world_size()
    if world_size == 1:
        return x
    x = x.contiguous()
    tensors = [torch.empty_like(x) for _ in range(world_size)]
    dist.all_gather(tensors, x)
    return torch.cat(tensors, dim=-1).contiguous()


def _split_last_dim(x):
    world_size = _world_size()
    if world_size == 1:
        return x
    chunk = _divide(x.size(-1), world_size)
    rank = _rank()
    return x[..., rank * chunk:(rank + 1) * chunk].contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all_reduce."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all_reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take this rank's slice of the last dim. Backward: all_gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _all_gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all_gather along last dim. Backward: take this rank's slice."""

    @staticmethod
    def forward(ctx, x):
        return _all_gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


def copy_to_parallel_region(x):
    return _CopyToParallelRegion.apply(x)


def reduce_from_parallel_region(x):
    return _ReduceFromParallelRegion.apply(x)


def scatter_to_parallel_region(x):
    return _ScatterToParallelRegion.apply(x)


def gather_from_parallel_region(x):
    return _GatherFromParallelRegion.apply(x)


# ---------------------------------------------------------------------------
# Layers
# ---------------------------------------------------------------------------

class ColumnParallelLinear(nn.Module):
    """Linear layer with weight split along the output dimension.

    Each rank holds weight of shape (out_features // world_size, in_features)
    and bias of shape (out_features // world_size,). The forward pass returns
    the full output (all_gather along the last dimension).
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.world_size = _world_size()
        self.rank = _rank()
        self.in_features = in_features
        self.out_features = out_features
        self.output_size_per_partition = _divide(out_features, self.world_size)

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )
        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = nn.Parameter(
            master_weight.detach()[start:end, :].clone().contiguous()
        )

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = copy_to_parallel_region(x)
        local_out = F.linear(x, self.weight, self.bias)
        return gather_from_parallel_region(local_out)


class RowParallelLinear(nn.Module):
    """Linear layer with weight split along the input dimension.

    Each rank holds weight of shape (out_features, in_features // world_size)
    and the full bias of shape (out_features,). The input may be either the
    full input (last dim == in_features), in which case each rank takes its
    slice, or an already-partitioned input (last dim == in_features //
    world_size). Partial outputs are summed with all_reduce and the bias is
    added once afterwards.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.world_size = _world_size()
        self.rank = _rank()
        self.in_features = in_features
        self.out_features = out_features
        self.input_size_per_partition = _divide(in_features, self.world_size)

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )
        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = nn.Parameter(
            master_weight.detach()[:, start:end].clone().contiguous()
        )

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        if x.size(-1) == self.input_size_per_partition and (
            self.world_size == 1 or x.size(-1) != self.in_features
        ):
            x_local = x
        elif x.size(-1) == self.in_features:
            x_local = scatter_to_parallel_region(x)
        else:
            raise ValueError(
                f"Input last dim {x.size(-1)} matches neither in_features "
                f"({self.in_features}) nor the per-rank partition "
                f"({self.input_size_per_partition})"
            )
        partial = F.linear(x_local, self.weight)
        out = reduce_from_parallel_region(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
